package io.github.cheshmakzanoon.portfolio.threadlens.agent;
import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.objectweb.asm.*;
class SafeHierarchyTest {
 private static ClassReader target(){return new ClassReader(bytes("sample/Target","java/lang/Object",new String[0],0));}
 private static byte[] bytes(String name,String parent,String[] interfaces,int access){ClassWriter w=new ClassWriter(0);w.visit(Opcodes.V25,access|Opcodes.ACC_PUBLIC,name,null,parent,interfaces);w.visitEnd();return w.toByteArray();}
 @Test void resolvesClassAndInterfaceMergesFromResourcesWithoutClassLoading(){var h=new SafeHierarchy(ClassLoader.getSystemClassLoader(),target());assertEquals("java/lang/String",h.common("java/lang/String","java/lang/String"));assertEquals("java/lang/Object",h.common("java/lang/String","java/lang/Object"));assertEquals("java/lang/Object",h.common("java/lang/Object","java/lang/String"));assertEquals("java/lang/Object",h.common("java/lang/String","java/lang/Integer"));assertEquals("java/lang/Object",h.common("java/util/List","java/util/Set"));assertThrows(IllegalArgumentException.class,()->h.common("[Ljava/lang/String;","java/lang/Object"));assertThrows(IllegalArgumentException.class,()->h.common("missing/Metadata","java/lang/Object"));}
 @Test void badMetadataResourcesAreRejectedRatherThanLoadingTargetTypes(){ClassLoader loader=new ClassLoader(){@Override public InputStream getResourceAsStream(String name){return new InputStream(){@Override public int read()throws IOException{throw new IOException("injected metadata read failure");}};}@Override public Class<?> loadClass(String name)throws ClassNotFoundException{throw new AssertionError("must never load a target class");}};assertThrows(IllegalArgumentException.class,()->new SafeHierarchy(loader,target()).common("bad/A","bad/B"));}
 @Test void hierarchyMetadataBudgetIsExplicit(){Map<String,byte[]> resources=new HashMap<>();for(int i=0;i<300;i++)resources.put("sample/T"+i+".class",bytes("sample/T"+i,i==299?"java/lang/Object":"sample/T"+(i+1),new String[0],0));ClassLoader loader=new ClassLoader(){@Override public InputStream getResourceAsStream(String name){byte[] b=resources.get(name);return b==null?super.getResourceAsStream(name):new ByteArrayInputStream(b);}};assertThrows(IllegalArgumentException.class,()->new SafeHierarchy(loader,target()).common("sample/T0","java/lang/String"));}
 @Test void packageLoaderModuleAndExactMethodScopeAreAuditable(){var p=new InstrumentationPolicy(List.of("sample.application"),List.of("selected"));assertTrue(p.selectClass(null,ClassLoader.getSystemClassLoader(),"sample/application/Target"));assertFalse(p.selectClass(null,null,"sample/application/Target"));assertFalse(p.selectClass(String.class.getModule(),ClassLoader.getSystemClassLoader(),"sample/application/Target"));for(String name:new String[]{"java/lang/String","javax/sql/DataSource","jdk/Thing","sun/Thing","org/objectweb/asm/Type","io/github/cheshmakzanoon/portfolio/threadlens/agent/Thing"})assertFalse(p.selectClass(null,ClassLoader.getSystemClassLoader(),name));assertFalse(p.selectClass(null,ClassLoader.getSystemClassLoader(),null));assertFalse(p.selectClass(null,ClassLoader.getSystemClassLoader(),"sample/other/Target"));assertFalse(p.selectMethod(0,"<init>"));assertFalse(p.selectMethod(0,"<clinit>"));assertFalse(p.selectMethod(Opcodes.ACC_NATIVE,"selected"));assertFalse(p.selectMethod(Opcodes.ACC_ABSTRACT,"selected"));assertFalse(p.selectMethod(0,"other"));assertTrue(p.selectMethod(0,"selected"));assertTrue(p.reasons().get("namedModule")>0);}
}
